update tax_rate set headline_rate = 3.5, rate_min = 1.7, rate_max = 3.5, threshold_amount = 3700000, threshold_note = 'The first €3m of the taxable base is taxed at 0%; the taxable base is net wealth after the €700,000 exemption, so the tax starts at €3.7m of net wealth.', note = 'Solidarity tax on large fortunes (ITSGF, Law 38/2022): 0% on the first €3m of taxable base, 1.7% to €5,347,998, 2.1% to €10,695,996, 3.5% above; the regional wealth tax paid for the same year is deducted from it (PwC Other taxes, last reviewed 30 Jun 2023). NOT ONE RATE: headline = the top band. Created on 28 Dec 2022 and charged on the 2022 tax period (accrual 31 Dec 2022); stated for 2022 in the PwC copy of 2023.', source_url = 'https://web.archive.org/web/20231216050645/https://taxsummaries.pwc.com/spain/individual/other-taxes', verified_on = '2023-12-16', next_check_on = '2027-01-15', needs_verification = false, valid_to = '2023-01-01' where jurisdiction_code = 'ES' and tax_type_code = 'WEALTH_SOLIDARITY' and valid_from = '2022-01-01';
