insert into tax_rate (jurisdiction_code, tax_type_code, valid_from, headline_rate, rate_min, rate_max, threshold_amount, threshold_note, note, source_url, verified_on, next_check_on, needs_verification) values ('ES-CB', 'CGT_FINANCIAL', '2026-01-01', 30, 19, 30, null, null, 'Common regime: the national savings scale applies in Cantabria. Savings income scale 19/21/23/27/30% (copied from the stored national 2026 row).', 'https://taxsummaries.pwc.com/spain/individual/taxes-on-personal-income', '2026-09-30', '2027-01-15', false) on conflict (jurisdiction_code, tax_type_code) where valid_to is null do update set headline_rate = excluded.headline_rate, rate_min = excluded.rate_min, rate_max = excluded.rate_max, threshold_amount = excluded.threshold_amount, threshold_note = excluded.threshold_note, note = excluded.note, source_url = excluded.source_url, verified_on = excluded.verified_on, next_check_on = excluded.next_check_on, needs_verification = excluded.needs_verification;
