-- ES-ML WEALTH_NET 2015-01-01..2016-01-01 (back-year) ← es-aeat-patrimonio
update tax_rate set headline_rate = 2.5, rate_min = 0.2, rate_max = 2.5, threshold_amount = 700000, threshold_note = 'Tax-free amount (mínimo exento) €700,000; the scale applies to the net wealth above it.', note = 'Melilla (an autonomous city without powers over this tax) applies the state rules: tax-free amount €700,000, the state scale (0.2% to 2.5%). No general rebate. NOT ONE RATE: the scale has 8 bands; headline = the top band. Ministry of Finance, "Tributación Autonómica. Medidas 2015", chapter I: it names every region that regulated the minimum, the scale or rebates in 2015; Melilla is not among them, so the state rules applied.', source_url = 'https://www.hacienda.gob.es/sgfal/financiacionterritorial/autonomica/cap%C3%ADtulo%20i%20tributaci%C3%B3n%20auton%C3%B3mica%202015%20v10%20web.pdf', verified_on = '2026-10-03', next_check_on = '2027-01-15', needs_verification = false, valid_to = '2016-01-01' where jurisdiction_code = 'ES-ML' and tax_type_code = 'WEALTH_NET' and valid_from = '2015-01-01';
